ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_meet_2"] = {
{"fw_l23_cr_dont_touch","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,8|mood=fear|out=stay2",{1,"There's a man lying in our yard who isn't moving - should I check him?",2,"Don't, don't touch him and don't kneel near his head",1,"He looks asleep",2,"They often do - leave him and stay up by the house"}},
{"fw_l23_cr_burnt_hands","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,12|mood=calm|world=building|out=stay2",{1,"I burned my hands pulling a pan from the stove - it's fine",2,"Let me see, that's a second-degree burn, it's not fine",1,"I can still hold things",2,"Cool it with water and I'll wrap it, you'll thank me tomorrow"}},
{"fw_l23_cr_need_blood","meet",2,"r1=civilian,family,worker|r2=rescue|x1=f|day=0,10|mood=grim|out=part",{1,"What would you tell somebody asking for blood for their husband?",2,"That it takes proper supplies and people who know what they're doing",1,"And without those?",2,"I wouldn't pretend we could improvise a transfusion. I'd try to get qualified help"}},
{"fw_l23_cr_i_am_so_tired","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,14|mood=sad|world=vehicle|out=stay1",{1,"You look exhausted - have you slept?",2,"Some, in the truck...",1,"Can I get you something? Bread, a cup of tea?",2,"Tea would be a kindness - thank you"}},
{"fw_l23_cr_crew_gone","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,10|mood=sad|out=part",{1,"Where's the rest of your crew?",2,"Three of us left from nine",1,"What happened?",2,"It happened fast, we lost two on the first call and the others on the second"}},
{"fw_l23_cr_quarantine_clinic","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,8|mood=grim|out=stay2",{1,"We heard there's a quarantine tent at the high school - should we go?",2,"That tent is for people showing symptoms, and there's no coming out once you're in",1,"So it's a trap",2,"It's a hard rule, whether it's right, I couldn't tell you - stay out unless you must"}},
{"fw_l23_cr_my_wife_is_sick","meet",2,"r1=civilian,family,worker|r2=rescue|x1=m|day=0,8|mood=fear|out=stay2",{1,"My wife has a cough and a fever, she wasn't bitten! She wasn't!",2,"I believe you! Sit with me a second - is she breathing fast?",1,"A little!",2,"Sounds like the ordinary kind, fluids and rest... I'll walk back with you and take a look"}},
{"fw_l23_cr_keep_the_children","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,14|mood=warm|out=stay1",{1,"We're sheltering about a dozen children at the grange - do you have anything for them?",2,"Crackers, a bottle of aspirin, the chewable kind",1,"That's more than we have - thank you",2,"Keep it away from the babies, count the dose by weight"}},
{"fw_l23_cr_dead_dog","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,14|mood=funny|world=road|out=part",{1,"I'm sorry to bother you, there's a dead dog in my road and I don't know what to do",2,"Is it moving?",1,"No",2,"Then cover it with a sheet, it's a small mercy and nobody will think less of you"}},
{"fw_l23_cr_first_aid_class","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,12|mood=calm|out=walk",{1,"I took the Red Cross course last spring - can I help you?",2,"What do you remember?",1,"Bleeding, bandaging, recovery position",2,"That's a hundred percent more than most - walk with me"}},
{"fw_l23_cr_pastor_shoes","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,14|mood=sad|world=road|out=part",{1,"Our pastor is gone, all we found were his shoes...",2,"I'm sorry - did anyone see which way?",1,"No, just the shoes, in the road",2,"Sometimes people leave them behind to move faster - keep that thought if it helps..."}},
{"fw_l23_cr_smoke_inhalation","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,12|mood=calm|out=part",{1,"My son keeps coughing from the smoke - is it dangerous?",2,"Open air, sit him upright, small sips of water",1,"How long until he's better?",2,"A day, if it gets worse, or his lips look blue, come find us"}},
{"fw_l23_cr_safe_house","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,14|mood=warm|out=part",{1,"Do you know any houses that are still safe?",2,"I can't promise you a safe house or somebody else's spare room",1,"Will they take strangers?",2,"You'd have to ask them. Saying I sent you wouldn't make them responsible for you"}},
{"fw_l23_cr_donated_blood","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,14|mood=funny|out=part",{1,"I gave blood last month, they gave me a cookie - this is what the cookie was for",2,"A fair trade, I suppose",1,"I'd like another cookie",2,"Find me one and I'll split it with you"}},
{"fw_l23_cr_scared_of_you","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,8|mood=fear|out=stay1",{1,"I'm sorry, I'm scared of anyone in a uniform right now",2,"You're allowed, I'd think less of you if you weren't careful",1,"How do I know you're not infected?",2,"Look at my eyes, check my hands, anything wrong, I'll be the one telling you to run"}},
{"fw_l23_cr_wake_the_town","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,12|hour=7,18|mood=calm|world=door,road|out=stay2",{1,"Should we sound the siren to warn people?",2,"Absolutely not, it will bring every one of them down the road",1,"Then how do we warn them?",2,"Door to door, quietly, in daylight"}},
{"fw_l23_cr_lost_the_baby","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,8|mood=sad|out=stay2",{1,"I lost my baby in the evacuation, I put her down for one second",2,"Where?",1,"At the Gulf station, there was a crowd, I was pushed",2,"Sit down here for a moment, tell me what she was wearing..."}},
{"fw_l23_cr_bees","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,14|mood=funny|out=part",{1,"I'm allergic to bee stings, I'm carrying around a pen, but it's expired",2,"Let me see it",1,"Two years past",2,"Better than nothing - keep it close and don't go near a hive"}},
{"fw_l23_cr_church_bell","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,8|hour=4,9|mood=fear|world=road|out=stay2",{1,"The church bell was ringing all night, nobody was in the tower",2,"Nobody!",1,"We checked! It was just... swinging",2,"I won't claim to know - stay off the street by the church until dawn"}},
{"fw_l23_cr_dust_masks","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,10|mood=calm|out=stay2",{1,"Do these masks work? We found a box at the hardware store",2,"Against dust, yes, against whatever this is, I don't know",1,"Should we wear them?",2,"They don't hurt - wear them if you're going near the bodies"}},
{"fw_l23_cr_look_for_family","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,12|mood=sad|out=stay2",{1,"I'm looking for my sister, thirty-four, blond, nurse at the county hospital...",2,"Did she have a name tag?",1,"Tammy - Tammy Roach",2,"I haven't treated a Tammy, I'll ask the crew when they're back - check the church board..."}},
{"fw_l23_cr_trade_bandages","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,12|mood=calm|out=part",{1,"We have two cases of bottled water - could we trade for some bandages?",2,"Gladly - take what you need, I'll take what you can spare",1,"That's very fair",2,"It's what's left of fair, anyway"}},
{"fw_l23_cr_old_hospital","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,8|mood=grim|out=part",{1,"We were going to try the hospital in town - is it worth it?",2,"I wouldn't, the ground floor is full",1,"Full of patients?",2,"Full of the other thing - don't go in"}},
{"fw_l23_cr_stay_calm","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,10|mood=calm|out=part",{1,"I can't stop shaking - is that normal?",2,"Entirely - sit down, put your head between your knees, breathe slowly",1,"I feel like an idiot",2,"You're not, I did the same on Saturday"}},
{"fw_l23_lm_who_has_the_bridge","meet",2,"r1=law,swat|r2=military,elite|day=0,10|mood=calm|out=stay2",{1,"Who's holding the bridge on 31W? I've got civilians asking",2,"Second platoon, nothing crosses without a pass from the lieutenant",1,"Do they know that?",2,"They will - tell them not to try it at night"}},
{"fw_l23_lm_jurisdiction","meet",2,"r1=law,swat|r2=military,elite|day=0,8|mood=angry|out=stay1",{1,"Sergeant, this is my county, I'd like to be told before your men move in",2,"Understood, Deputy! Orders came down in a hurry!",1,"Then let's agree to trade radio channels and talk before anyone does anything",2,"I can do that, channel nine, on the hour"}},
{"fw_l23_lm_head_count","meet",2,"r1=law,swat|r2=military,elite|day=0,10|mood=calm|out=part",{1,"How many do you have in the cordon?",2,"Not enough, and I'm not giving you a number",1,"Fair, I've got six deputies and a dispatcher without a phone",2,"Then between us we've got a very short list"}},
{"fw_l23_lm_orders_unclear","meet",2,"r1=law,swat|r2=military,elite|day=0,8|mood=grim|out=stay2",{1,"What are your orders, exactly?",2,"Contain the area and hold the line - Beyond that, I get nothing",1,"Nothing as in nothing?",2,"The last radio call was Saturday at 0400, since then I've been guessing"}},
{"fw_l23_lm_civilians_loose","meet",2,"r1=law,swat|r2=military,elite|day=0,10|mood=angry|world=fence,water|out=stay1",{1,"You have civilians on my side of the river, walking, with rifles",2,"Yes, we're trying to send them home",1,"Let me talk to them, they know my face",2,"Appreciated! Keep them away from the fence line"}},
{"fw_l23_lm_warrant","meet",2,"r1=law,swat|r2=military,elite|x1=m|day=0,12|mood=funny|out=part",{1,"I need to see your search authority before your men go into those houses",2,"Deputy, I have a rifle and an order, that's my authority",1,"It's not a warrant",2,"No, sir, it's an emergency, I'll sign whatever you like after"}},
{"fw_l23_lm_shared_target","meet",2,"r1=law,swat|r2=military,elite|day=0,10|mood=calm|out=part",{1,"There's a pack of them behind the feed store, fifteen, maybe twenty",2,"Roger, we're about two hundred meters south, could hit them from the lot",1,"Do it quiet, my people are on the other side of the building",2,"Copy, we'll wait for you to clear the rear first"}},
{"fw_l23_lm_dispatch","meet",2,"r1=law,swat|r2=military,elite|day=0,8|mood=sad|out=stay1",{1,"Have you heard from state police? Anyone at all?",2,"Negative, I tried every channel I know",1,"Same, my dispatcher's been asking for ten hours",2,"Maybe the repeater's down, maybe more than that..."}},
{"fw_l23_lm_chain_of_custody","meet",2,"r1=law,swat|r2=military,elite|day=0,12|mood=funny|out=part",{1,"If you shoot a man, I still have to write it up",2,"I'll put it in my log, Deputy",1,"Do you have a form?",2,"I have a pencil, we'll make do"}},
{"fw_l23_lm_bad_news","meet",2,"r1=law,swat|r2=military,elite|day=0,8|mood=grim|out=part",{1,"I heard you lost a squad at the rail yard",2,"We did, the rest of the platoon is on edge",1,"What happened?",2,"They went in through the front - don't ever do that"}},
{"fw_l23_lm_deserters","meet",2,"r1=law,swat|r2=military,elite|day=0,10|mood=angry|out=part",{1,"There are men in Army fatigues stealing from houses out by Muldraugh",2,"Not ours, I hope",1,"How can I tell?",2,"Ours carry radios and keep their rifle slung, the ones you describe do neither"}},
{"fw_l23_lm_swap_ammo","meet",2,"r1=law,swat|r2=military,elite|day=0,12|mood=calm|out=part",{1,"We're low on 12-gauge - can you spare any?",2,"Not a lot, I can give you two boxes if you give me one of your radios",1,"One radio for two boxes - done",2,"Pleasure doing business, Deputy"}},
{"fw_l23_lm_curfew_enforce","meet",2,"r1=law,swat|r2=military,elite|day=0,8|mood=calm|world=road|out=stay2",{1,"Will your men back me on the curfew?",2,"To the extent we're able, we can't patrol every block",1,"Just the main road then",2,"The main road we can do"}},
{"fw_l23_lm_dont_shoot_us","meet",2,"r1=law,swat|r2=military,elite|day=0,8|mood=fear|world=cars|out=stay1",{1,"Last night one of yours put a round through my cruiser's windshield",2,"My apologies, it was dark and the lights were on",1,"Turn off the sentry's fire-on-sight order for county vehicles, please",2,"I'll relay it up"}},
{"fw_l23_lm_where_do_you_sleep","meet",2,"r1=law,swat|r2=military,elite|day=0,14|mood=calm|world=stairs,building|out=part",{1,"Where are your men bunking?",2,"School gym, it's got two exits and walls",1,"We've got the courthouse, stone basement, one stairwell",2,"Sounds defensible - keep it that way"}},
{"fw_l23_lm_reservists","meet",2,"r1=law,swat|r2=military,elite|day=0,12|mood=sad|out=part",{1,"Most of my men are weekend reservists, they've got families right here in the county...",2,"That's hard",1,"They're leaving post at night to check on their kids...",2,"I'd let them, a man who doesn't know where his kids are is no good on the line"}},
{"fw_l23_lm_medical_supply","meet",2,"r1=law,swat|r2=military,elite|day=0,12|mood=calm|out=walk",{1,"We have a deputy with a gunshot wound - your medic around?",2,"He's with the trucks - bring him over, Deputy",1,"We'll carry him",2,"Follow me, the aid station is two blocks"}},
{"fw_l23_lm_bad_maps","meet",2,"r1=law,swat|r2=military,elite|day=0,12|mood=funny|out=part",{1,"Your map's out of date, the old bridge was torn down a decade ago",2,"This is the map I was handed",1,"I grew up here, Sergeant, I can draw you a better one",2,"That would be helpful"}},
{"fw_l23_lm_what_you_saw","meet",2,"r1=law,swat|r2=military,elite|day=0,8|hour=4,9|mood=grim|out=part",{1,"What did you see at the Louisville line?",2,"Roadblocks and fire, we turned back before dawn",1,"Did anyone get through?",2,"Nobody I could see"}},
{"fw_l23_lm_press","meet",2,"r1=law,swat|r2=military,elite|day=0,14|mood=funny|out=stay1",{1,"There's a reporter in my town asking us to comment - do I say anything?",2,"Tell him it's an ongoing situation",1,"That's what we always say",2,"And it's always true"}},
{"fw_l23_lm_a_name_on_the_list","meet",2,"r1=law,swat|r2=military,elite|day=0,10|mood=sad|out=part",{1,"You have a casualty list?",2,"I keep one, names and unit",1,"I keep one too, mine is civilians...",2,"Let's compare, maybe we can put names to the unknowns"}},
{"fw_l23_lm_dogs","meet",2,"r1=law,swat|r2=military,elite|day=0,14|mood=calm|out=part",{1,"I used to think my K-9 knew trouble before I did. Wish I had that feeling again",2,"How was he around gunfire?",1,"Better than most of my deputies",2,"I'd have liked to meet him"}},
{"fw_l23_lm_rumors_out","meet",2,"r1=law,swat|r2=military,elite|day=0,8|mood=grim|out=part",{1,"People are saying the Army will pull out and burn the county",2,"I haven't heard that",1,"I'd like you to tell me if you do",2,"If I hear it, you'll be the second to know"}},
{"fw_l23_lm_help_with_roadblock","meet",2,"r1=law,swat|r2=military,elite|day=0,12|mood=calm|out=walk",{1,"We need hands at the roadblock on Route 60",2,"How many?",1,"Four if you can spare them",2,"I can spare three, we'll ride out together"}},
{"fw_l23_lm_cold_coffee","meet",2,"r1=law,swat|r2=military,elite|day=0,14|mood=funny|world=building|out=part",{1,"Coffee? It's been on the stove since Saturday",2,"Sounds like a challenge",1,"It's more of a threat",2,"I'll take two"}},
{"fw_l23_lm_ask_for_a_pass","meet",2,"r1=law,swat|r2=military,elite|day=0,10|mood=calm|out=part",{1,"One of my deputies has a sister on the other side - can you issue a pass?",2,"I'm not authorized",1,"Who is?",2,"The lieutenant, he's at the staging area - ask him in the morning"}},
{"fw_l23_lm_old_friend","meet",2,"r1=law,swat|r2=military,elite|x1=m|day=0,14|mood=warm|out=part",{1,"Aren't you Danny Walsh's boy? From the VFW?",2,"Yes, sir, he's my father",1,"I wore a badge when you were in diapers",2,"Then I'm in good hands today"}},
{"fw_l23_lm_dont_let_them_see","meet",2,"r1=law,swat|r2=military,elite|day=0,8|mood=grim|out=part",{1,"We buried a few on the school grounds, I don't want the children seeing it",2,"Understood... I'll have the digging detail go behind the gym",1,"I'd appreciate that",2,"It's a hard thing to ask of a man... I'll see it's done respectfully"}},
{"fw_l23_lm_whiskey","meet",2,"r1=law,swat|r2=military,elite|day=0,14|mood=funny|out=part",{1,"One of your privates offered one of my deputies a bottle of Jim Beam",2,"Which private?",1,"Kid with the red hair",2,"I'll speak to him, thank you for the report"}},
{"fw_l23_lm_hold_the_line","meet",2,"r1=law,swat|r2=military,elite|day=0,8|mood=grim|world=road|out=stay2",{1,"We're falling back to the courthouse, the east side is too thin",2,"We're holding here, this position is tied to the road",1,"You'll be overrun",2,"Possibly, but if we leave, nobody's covering the road"}},
{"fw_l23_lm_split_the_town","meet",2,"r1=law,swat|r2=military,elite|day=0,10|mood=calm|out=part",{1,"Let's divide the town, you take everything south of the tracks",2,"Agreed, north of the tracks is yours",1,"And if either of us needs help?",2,"Three shots, spaced, then wait - we'll come"}},
{"fw_l23_lm_confiscate","meet",2,"r1=law,swat|r2=military,elite|day=0,8|mood=angry|out=part",{1,"I heard you took weapons from a family on Plum Street",2,"We secured a rifle that had been fired at a patrol",1,"They were scared, Sergeant!",2,"So were we, return it to them if you wish, I won't stop you"}},
{"fw_l23_lm_nights_worse","meet",2,"r1=law,swat|r2=military,elite|day=0,8|hour=16,22|mood=fear|world=vehicle|out=stay2",{1,"Anything different about the nights lately?",2,"I hate trying to find a way through in the dark. More guessing than I care for",1,"I'd rather look for a place before it gets that late",2,"Then let's stop arguing and look"}},
{"fw_l23_lm_paperwork","meet",2,"r1=law,swat|r2=military,elite|day=0,14|mood=funny|out=part",{1,"I filed a missing persons report for forty-one people today",2,"Who reads it?",1,"I do - every night",2,"That might be the most honest thing anybody's done this week"}},
{"fw_l23_lm_shared_fear","meet",2,"r1=law,swat|r2=military,elite|day=0,8|mood=sad|world=vehicle,building|out=part",{1,"You ever see a thing you can't write up?",2,"Every day since Friday...",1,"I stood in a kitchen with a woman who had her own husband's arm in her teeth - four feet from me...",2,"So what'd you do?",1,"What the training said... then I went outside and sat in the cruiser"}},
{"fw_l23_lm_hand_over_prisoners","meet",2,"r1=law,swat|r2=military,elite|day=0,8|mood=angry|world=vehicle|out=stay2",{1,"I have three men in the holding cell who need to be somewhere",2,"Are they infected?",1,"No, they're drunks and a car thief - I can't feed them",2,"Release them, I can't take custody of anyone"}},
{"fw_l23_lm_who_shoots_first","meet",2,"r1=law,swat|r2=military,elite|day=0,8|mood=angry|out=part",{1,"We need an understanding about warnings before somebody gets shot",2,"We shout, we fire one over their heads, then we shoot",1,"My men have been told to shout, nothing else",2,"Then we tell our people about each other, before a patrol crosses wrong"}},
{"fw_l23_lm_grandmother_story","meet",2,"r1=law,swat|r2=military,elite|day=0,14|mood=warm|out=part",{1,"My grandmother used to say the army would always come back for you",2,"Mine said it was a lie they tell at funerals",1,"Which one of them was right?",2,"I'm still waiting to find out"}},
{"fw_l23_lm_the_priest","meet",2,"r1=law,swat|r2=military,elite|day=0,10|hour=16,5|mood=sad|out=part",{1,"Father Doyle is still ringing his bell every evening, hundreds show up...",2,"Is that an order?",1,"No, they just come",2,"I'd rather they didn't gather in one place after dark - but I wouldn't be the one to tell him"}},
{"fw_l23_lm_flare_gun","meet",2,"r1=law,swat|r2=military,elite|day=0,12|mood=calm|world=building,rooftop,road|out=part",{1,"If you see trouble in the south end, fire a flare",2,"Red or white?",1,"Red means stop. White means come over. Still look before you move",2,"Understood, we'll put someone on the roof"}},
{"fw_l23_lm_what_you_ate","meet",2,"r1=law,swat|r2=military,elite|x1=m|day=0,14|mood=funny|world=vehicle|out=part",{1,"When did you last eat something warm?",2,"Yesterday, beans from a can, heated on the engine block",1,"My wife's church has a pot of chili going on Cedar - tell your men",2,"I'll send a detail, thank you, Deputy"}},
{"fw_l23_lm_news_from_fort","meet",2,"r1=law,swat|r2=military,elite|day=0,8|mood=grim|out=part",{1,"Anything from Fort Knox?",2,"They're still there, they're not answering",1,"How do you know they're still there?",2,"Because the lights haven't gone out"}},
{"fw_l23_lm_take_the_prisoner","meet",2,"r1=law,swat|r2=military,elite|day=0,8|mood=angry|out=walk",{1,"I have a man who put a bullet in a deputy last night - he's cuffed",2,"I'll take him! We can hold him with ours",1,"Understood! I'll bring him to your truck myself",2,"Wait until the patrol's back! I'll send two to escort"}},
{"fw_l23_lm_last_cigarette","meet",2,"r1=law,swat|r2=military,elite|day=0,14|mood=funny|out=part",{1,"You smoke?",2,"I did, I quit in March",1,"Want one?",2,"... Yes"}},
{"fw_l23_nt_stop_there","meet",2,"day=0,3650|mood=calm|out=part",{1,"Hold up - are you bitten, either of you?",2,"No, are you?",1,"No, just making sure before anyone gets closer",2,"Yeah ok, we'll stay put"}},
{"fw_l23_nt_which_way","meet",2,"day=0,3650|mood=calm|world=vehicle,road|out=part",{1,"Which way did you come from?",2,"North, up the highway, it's bad at the junction",1,"How bad?",2,"Enough that we left a good truck on the shoulder"}},
{"fw_l23_nt_seen_anyone","meet",2,"day=0,3650|hour=4,11|mood=grim|world=road|out=part",{1,"Seen anyone else on the road?",2,"A man with a cart, early this morning, he didn't stop",1,"Which direction?",2,"Toward the ridge, I wouldn't follow him"}},
{"fw_l23_nt_water_spot","meet",2,"day=0,3650|mood=calm|out=part",{1,"Do you know where a person can find clean water around here?",2,"There's a spring behind the quarry, if you don't mind the walk",1,"Is it guarded?",2,"Nobody I saw - take the left fork at the broken sign"}},
{"fw_l23_nt_big_noise","meet",2,"day=0,3650|mood=fear|world=vehicle,building|out=part",{1,"Did you hear that crash last night?",2,"Half the town did, it sounded like a truck going through a wall",1,"Think it brought something with it?",2,"I think everything within a mile came to look"}},
{"fw_l23_nt_trade_ammo","meet",2,"day=0,3650|mood=calm|out=part",{1,"Any spare shells for a twelve-gauge?",2,"A few - what can you give me?",1,"Two cans of soup and a lighter",2,"Make it three cans and we'll talk"}},
{"fw_l23_nt_dont_know_you","meet",2,"day=0,3650|mood=angry|out=part",{1,"I don't know you, so I'm not going to say too much",2,"That's smart! I don't know you either",1,"Then we understand each other!",2,"Just keep your hands where I can see them"}},
{"fw_l23_nt_tired","meet",2,"day=0,3650|mood=sad|out=part",{1,"You look like you haven't slept in days...",2,"I stopped keeping count",1,"There's a safe corner back there if you need it",2,"I'll keep that in mind - thanks"}},
{"fw_l23_nt_heading_south","meet",2,"day=0,3650|mood=calm|world=road|out=walk",{1,"We're headed south, if you're going that way you're welcome to walk with us",2,"How far?",1,"A few miles, we know the road",2,"Then we'll tag along"}},
{"fw_l23_nt_dead_ahead","meet",2,"day=0,3650|mood=fear|world=road|out=part",{1,"There are bodies ahead on the road, you may not want to look",2,"Are they moving?",1,"Not that I could tell",2,"Then we'll go the long way around"}},
{"fw_l23_nt_trust_a_stranger","meet",2,"day=0,3650|mood=warm|out=part",{1,"I had a stranger give me a canteen yesterday, didn't ask my name",2,"I try to be that stranger when I can",1,"It helped more than you'd think",2,"It helps the one who gives it too"}},
{"fw_l23_nt_dont_stop","meet",2,"day=0,3650|mood=calm|world=road|out=part",{1,"Don't park yourselves here, this road's no place to stop",2,"Understood, we were just about to leave",1,"Take the shoulder, stay off the pavement",2,"Thanks for the warning"}},
{"fw_l23_nt_lost_somebody","meet",2,"day=0,3650|mood=sad|out=part",{1,"I lost someone in the last few days",2,"I'm sorry",1,"I don't want to talk about it... I only wanted someone to know...",2,"Consider it known"}},
{"fw_l23_nt_sharing_a_fire","meet",2,"day=0,3650|mood=warm|out=walk",{1,"There's a fire behind the garage if you want to warm up",2,"Is it safe?",1,"It's small, we keep it under a tarp so the light doesn't carry",2,"Then lead the way, we could use a hot meal"}},
{"fw_l23_nt_weapons_down","meet",2,"day=0,3650|mood=fear|out=part",{1,"Lower the gun, please, we aren't looking for trouble",2,"Neither are we, I'll lower it if you do",1,"At the same time?",2,"Now"}},
{"fw_l23_nt_big_dog","meet",2,"day=0,3650|mood=funny|out=part",{1,"Is that dog friendly?",2,"Mostly, he's afraid of cats",1,"Ha! Cats, I'll write that down",2,"Don't tell him we're keeping you"}},
{"fw_l23_nt_signs_of_infection","meet",2,"day=0,3650|mood=fear|out=part",{1,"Check your shirt for blood, will you? Just in case!",2,"It's mine, from a nosebleed!",1,"Turn around, let me see your back",2,"... All right... nothing there!"}},
{"fw_l23_nt_old_church","meet",2,"day=0,3650|hour=4,11|mood=calm|world=building|out=walk",{1,"There's an old church that's been standing since the flood - stone walls",2,"Is it empty?",1,"It was this morning",2,"Thank you, we'll check it before dark"}},
{"fw_l23_nt_no_help","meet",2,"day=0,3650|mood=angry|out=part",{1,"Please, we need food for our children",2,"I'm sorry, I have none to spare",1,"Not even a little?",2,"I wish I could, I would if I had it"}},
{"fw_l23_nt_directions","meet",2,"day=0,3650|mood=calm|world=water,road|out=walk",{1,"The creek road gets us to the highway?",2,"It does, but the bridge is out",1,"Then how do we cross?",2,"There's a shallow stretch past the second bend - watch for the current"}},
{"fw_l23_nt_hope","meet",2,"day=0,3650|mood=warm|out=part",{1,"Do you think anyone's going to come?",2,"I think someone is, I don't know when",1,"That's more hopeful than I expected",2,"It's the only way I get up in the morning"}},
{"fw_l23_nt_mistrust_the_quiet","meet",2,"day=0,3650|mood=fear|out=stay2",{1,"Too quiet here - do you hear anything?",2,"Nothing",1,"That's what worries me!",2,"Let's not stay long"}},
{"fw_l23_nt_borrow_a_match","meet",2,"day=0,3650|mood=funny|out=part",{1,"Do you have a light?",2,"I've got a match and a prayer",1,"I'll take the match",2,"Fair, keep the prayer for later"}},
{"fw_l23_nt_we_are_leaving","meet",2,"day=0,3650|hour=4,9|mood=calm|world=water|out=walk",{1,"We're leaving at first light, you're welcome to join",2,"Where to?",1,"The river valley, we hear it's quieter",2,"We'll think about it tonight"}},
{"fw_l23_nt_whistle_codes","meet",2,"day=0,3650|mood=calm|out=part",{1,"If you hear two whistles, it means come quick, one means all clear",2,"Got it, two means come, one means clear",1,"Right, don't whistle for fun",2,"I'll hold my tongue"}},
{"fw_l23_nt_take_the_map","meet",2,"day=0,3650|mood=calm|world=road|out=part",{1,"Would you trust an old map to get you out of trouble?",2,"For finding a road, maybe. Not for knowing what's on it",1,"That's what worries me. Easy to follow a line without looking",2,"Then we look. An extra minute won't offend the map"}},
{"fw_l23_nt_hungry_dog","meet",2,"day=0,3650|mood=sad|out=part",{1,"Your dog looks hungry",2,"So are we, he gets first pick...",1,"Here's some jerky",2,"Thank you... I don't know what to say"}},
{"fw_l23_nt_curfew_sort_of","meet",2,"day=0,3650|hour=16,22|mood=calm|out=part",{1,"We try not to move after sundown",2,"Why?",1,"They see better than we do in the dark",2,"I hadn't thought about that"}},
{"fw_l23_nt_nobody_answers","meet",2,"day=0,3650|mood=grim|world=building|out=part",{1,"I called out for an hour at the farmhouse and nobody answered",2,"Did you go in?",1,"Only the porch, there was a smell",2,"Then don't, don't go any further"}},
{"fw_l23_nt_one_bullet","meet",2,"day=0,3650|mood=grim|out=part",{1,"I have one bullet left, I'm keeping it for the right moment",2,"What moment is that?",1,"Whichever one it is",2,"I hope it doesn't come"}},
{"fw_l23_nt_a_good_boot","meet",2,"day=0,3650|mood=funny|out=part",{1,"Nice boots - where did you find them?",2,"Off a man who wouldn't be needing them",1,"Did he mind?",2,"He didn't say"}},
{"fw_l23_nt_bees","meet",2,"day=0,3650|mood=warm|out=part",{1,"There's a hive in the oak behind the shed, honey if you can reach it",2,"Won't they sting?",1,"Only if you startle them - move slowly",2,"I'll try, we haven't had anything sweet in a week"}},
{"fw_l23_nt_light_in_the_window","meet",2,"day=0,3650|mood=fear|out=stay2",{1,"See that light in the farmhouse?",2,"Yes",1,"It's been on since yesterday, nobody's come out",2,"Let's go around!"}},
{"fw_l23_nt_can_you_read","meet",2,"day=0,3650|mood=funny|out=part",{1,"Can you read what's on that sign? My eyes aren't what they were",2,"It says Next gas 40 miles",1,"That's not much help anymore",2,"No, but I'm glad somebody wrote it"}},
{"fw_l23_nt_make_yourself_small","meet",2,"day=0,3650|mood=fear|world=vehicle|out=stay2",{1,"Down - get down behind the car",2,"What is it?",1,"Something at the corner, I can't see it yet",2,"I'll keep my head low!"}},
{"fw_l23_nt_what_day","meet",2,"day=0,3650|mood=funny|out=part",{1,"Do you know what day it is?",2,"I stopped counting around Tuesday",1,"Then it might be Tuesday",2,"Fine by me"}},
{"fw_l23_nt_found_a_radio","meet",2,"day=0,3650|hour=16,22|mood=warm|world=vehicle|out=part",{1,"I found a working radio in the trunk of an abandoned car",2,"Anything on it?",1,"Just static, but the battery's good",2,"Keep trying at dusk, that's when the signal carries"}},
{"fw_l23_nt_gate_closed","meet",2,"day=0,3650|mood=angry|out=part",{1,"If somebody's blocked a lane, would you go over anyway?",2,"Could be protecting their home. Could be something else. We don't know",1,"So you'd leave it alone?",2,"I'd look for another way before I climbed into somebody's business"}},
{"fw_l23_nt_sorry_for_staring","meet",2,"day=0,3650|mood=warm|out=part",{1,"Sorry for staring, it's been days since I saw a clean face",2,"No offense taken, you look the same as I do",1,"Tired?",2,"Tired and surprised we're talking"}},
{"fw_l23_nt_leaving_note","meet",2,"day=0,3650|mood=calm|world=door|out=part",{1,"We leave notes on doors for anyone who comes after",2,"What do they say?",1,"Which way we went and what we left behind",2,"That's decent of you"}},
{"fw_l23_nt_hold_on_to_it","meet",2,"day=0,3650|mood=sad|out=part",{1,"Keep your head up, I know it sounds foolish",2,"It doesn't",1,"There's a lot of us still out here",2,"Thank you, I needed to hear that"}},
{"fw_l23_sv_you_alive","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,8|hour=4,11|mood=fear|world=water|out=part",{1,"Oh thank God, another person - are you bitten?",2,"No, you?",1,"No, I wasn't sure anyone else was left",2,"I met a family at the creek this morning, so there's a few of us"}},
{"fw_l23_sv_trade_batteries","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,14|mood=calm|out=part",{1,"Do you have any D batteries? Our flashlight died",2,"I have four - what've you got?",1,"A can of green beans and a jar of peanut butter",2,"Deal, the peanut butter is the real treasure"}},
{"fw_l23_sv_what_did_you_see","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,8|mood=fear|world=road|out=part",{1,"Where did you come from?",2,"Rosewood, the whole street was moving, and I don't mean people",1,"Moving how?",2,"Dragging - slow, but there were so many of them"}},
{"fw_l23_sv_rumor_helicopters","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,8|mood=fear|out=part",{1,"You hear the helicopters last night?",2,"Every one of them, they flew low over the water tower",1,"Think they're looking for us?",2,"I think they're looking for whatever they can't find"}},
{"fw_l23_sv_gas_tip","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,14|mood=calm|out=part",{1,"There's a pump at the farm on Dixie Highway with gas still in the tank - needs a hand crank",2,"Huh, says who?",1,"I filled up there last night",2,"Thanks, I'll be careful on the approach"}},
{"fw_l23_sv_lost_wife","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,10|mood=sad|out=part",{1,"I was out getting medicine when it started, when I came back she wasn't home",2,"Did you look for her?",1,"Everywhere, her car's still in the drive",2,"Maybe she walked to her sister's... I'd believe that if I were you..."}},
{"fw_l23_sv_whats_it_called","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,12|mood=funny|out=part",{1,"Does this thing have a name yet?",2,"My uncle calls them zombies, my neighbor says the sick ones",1,"What do you call them?",2,"Anything that gets me out of saying what they used to be"}},
{"fw_l23_sv_dont_go_to_louisville","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,8|mood=grim|out=part",{1,"We were thinking Louisville",2,"Don't, a guy came through yesterday from there, his eyes were wrong",1,"Wrong how?",2,"He said the city's lights are all out, he said he walked through the middle of it and nobody said a word"}},
{"fw_l23_sv_news_quarantine","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,8|mood=grim|world=road|out=part",{1,"They said on the radio the whole county's sealed",2,"Sealed how? There's a hundred roads",1,"The Army's got them all, even the farm tracks",2,"Then we're in a box"}},
{"fw_l23_sv_cry_together","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,14|mood=sad|out=part",{1,"I keep thinking I'll see my mom come around that corner",2,"I keep thinking the same about my dad",1,"Does it get better?",2,"Not yet... but it's easier when there's someone nearby"}},
{"fw_l23_sv_swap_clothes","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,14|mood=warm|world=rain|out=part",{1,"You wouldn't happen to have a spare pair of socks?",2,"Two pairs - are you short?",1,"Mine are soaked through, it's been three days",2,"Here, feet matter more than anything right now"}},
{"fw_l23_sv_dog_barking","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,8|mood=fear|out=part",{1,"Our dog wouldn't stop barking that first night. I thought I'd go mad",2,"Mine used to bark at anything that moved",1,"I kept thinking it would bring them",2,"And I kept yelling his name. Like that was helping anybody"}},
{"fw_l23_sv_bridge_story","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,8|mood=grim|world=cars,road|out=part",{1,"Did you hear what happened on the Ohio River bridge?",2,"No",1,"They shot at the cars, everyone trying to get out - people on the road with their hands up",2,"I don't believe that - I won't"}},
{"fw_l23_sv_found_a_gun","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,14|mood=calm|world=vehicle|out=walk",{1,"Do you know how to use this? I found it in a truck",2,"Let me see, it's a revolver - hold it flat, don't wave it",1,"Is it loaded?",2,"Five rounds, treat it like it's always loaded"}},
{"fw_l23_sv_barn_safe","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,12|mood=calm|out=walk",{1,"There's an old tobacco barn on the ridge, we've been sleeping there",2,"Is it high enough to see them coming?",1,"You can see the entire valley, we keep a lantern low",2,"Good, can we stay a night?"}},
{"fw_l23_sv_stay_quiet","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,8|mood=fear|world=road|out=stay1",{1,"Whisper, there's a pack at the end of the street",2,"How big?",1,"Six or seven, they're standing there like they forgot what they were doing",2,"Move slow, don't look at them, they notice eyes"}},
{"fw_l23_sv_trade_news","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,14|hour=16,22|mood=calm|out=part",{1,"What have you heard?",2,"The AM station comes back around dusk, a man reads names",1,"What names?",2,"People who've been found, it's short, but it's something"}},
{"fw_l23_sv_old_man_garden","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,14|mood=warm|world=building|out=part",{1,"An old man on Walnut Street still waters his tomatoes every evening",2,"Seriously?",1,"Sits on the porch with a rifle and a hose - waved at me",2,"I hope he's all right, I hope there's still tomatoes"}},
{"fw_l23_sv_no_trust","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,10|mood=angry|out=part",{1,"If we find food, don't tell everybody we can share it before we know how much",2,"I'm not promising anything",1,"I know. I just hate having to say no",2,"Then we'll be honest. Better than making somebody count on us"}},
{"fw_l23_sv_fix_my_car","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,14|mood=warm|world=vehicle|out=walk",{1,"Do you know anything about engines? Ours made a noise and stopped",2,"A little, pop the hood",1,"We'd be grateful, we can travel together if it runs",2,"Let's see what it is first"}},
{"fw_l23_sv_baby_cries","meet",2,"r1=civilian,family,worker|r2=civilian,family,worker|day=0,8|mood=fear|out=part",{1,"I still hear that baby crying from the shelter",2,"Her mother kept saying she was hungry",1,"I wish I'd known what to offer. Milk powder isn't something you just guess at",2,"I didn't even ask the mother's name"}},
}
